// Rule L2: the GLSL spellings 1.x accepted, written as HLSL.

/// @sort 32
uniform float3 A = float3(1.0, 0.0, 0.0);
/// @sort 32
uniform float3 B = float3(0.0, 0.0, 1.0);
/// @sort 32
uniform float T = 0.25;

/// @name DreamShaderTests/Migrate/M_MgGlsl
export void M_MgGlsl(inout material Base)
{
    float3 Color = float3(0, 0, 0);
    float3 Mixed = lerp(A, B, T);
    Color = frac(Mixed * 4.0) + fmod(Mixed, 0.5);
    Base.EmissiveColor = Color;
}
